<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$rows=$pdo?$pdo->query('SELECT id,product_name,merchant,status,featured FROM products ORDER BY updated_at DESC')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Affiliate Products</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Affiliate Products</h1><p><a class="btn" href="product-edit.php">New product</a> <a href="dashboard.php">Dashboard</a></p><div class="card" style="overflow:auto"><table style="width:100%"><tr><th>Product</th><th>Merchant</th><th>Status</th><th>Featured</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['merchant']??'')?></td><td><?=e($r['status'])?></td><td><?=((int)$r['featured'])?'Yes':'No'?></td><td><a href="product-edit.php?id=<?=$r['id']?>">Edit</a> · <a href="product-delete.php?id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php if(!$rows):?><p class="muted">No products found.</p><?php endif;?></div></main></body></html>
